  ('Business Clearance', 'Video Game Shop (Per Unit)', null, date '2026-11-22', array['Business Clearance', 'Plate', 'Inspection Fee', 'Sticker', 'Penalty', 'No. of Employee', 'Per unit: ₱150 each (enter the total)'], array[0.00, 150.00, 50.00, 100.00, 0.00, 50.00, 150.00]::numeric[], 'Loaded from the photos of the 2019 Revised Revenue Code (encoded and cross-checked 2026-11-18). Confirmed by the barangay in writing (2026-11-22): per unit only: 150 per unit, no 500 base. No. of Employee holds 50 per head; the system multiplies it by the number of employees. Staff pick the size and the inspection fee (small 50 / big 100) from the photo of the business (written answers 2026-11-22). Per-unit fee: the line holds one unit; Staff enter the total for the actual number of units.'),
  ('Business Clearance', 'Watch Store', null, date '2026-11-22', array['Business Clearance', 'Plate', 'Inspection Fee', 'Sticker', 'Penalty', 'No. of Employee'], array[500.00, 150.00, 50.00, 100.00, 0.00, 50.00]::numeric[], 'Loaded from the photos of the 2019 Revised Revenue Code (encoded and cross-checked 2026-11-18). No. of Employee holds 50 per head; the system multiplies it by the number of employees. Staff pick the size and the inspection fee (small 50 / big 100) from the photo of the business (written answers 2026-11-22).'),
  ('Business Clearance', 'Wine, Liquor & Beverages Store', null, date '2026-11-22', array['Business Clearance', 'Plate', 'Inspection Fee', 'Sticker', 'Penalty', 'No. of Employee'], array[750.00, 150.00, 50.00, 100.00, 0.00, 50.00]::numeric[], 'Loaded from the photos of the 2019 Revised Revenue Code (encoded and cross-checked 2026-11-18). No. of Employee holds 50 per head; the system multiplies it by the number of employees. Staff pick the size and the inspection fee (small 50 / big 100) from the photo of the business (written answers 2026-11-22).')
  ) as v(clearance_type, category, classification, effective_date, names, amounts, notes)
  loop
    sched_id := null;
    select s.id into sched_id from public.fee_schedules s
    join public.clearance_types t on t.id = s.clearance_type_id and t.name = r.clearance_type
    left join public.business_categories c on c.id = s.business_category_id
    left join public.business_classifications k on k.id = s.classification_id
    where s.effective_date = r.effective_date and s.ordinance_reference = 'Revised Revenue Code of Barangay San Jose, Chapter V (Sangguniang Barangay session, 3 December 2019)' and s.reason_notes = r.notes
      and c.name is not distinct from r.category and k.name is not distinct from r.classification
    limit 1;
    if sched_id is null then
      insert into public.fee_schedules (clearance_type_id, business_category_id, classification_id, effective_date, ordinance_reference, reason_notes, created_by)
      select t.id, c.id, k.id, r.effective_date, 'Revised Revenue Code of Barangay San Jose, Chapter V (Sangguniang Barangay session, 3 December 2019)', r.notes, null
      from public.clearance_types t
      left join public.business_categories c on c.name = r.category
      left join public.business_classifications k on k.category_id = c.id and k.name = r.classification
      where t.name = r.clearance_type
      returning id into sched_id;
    end if;
    if sched_id is null then raise exception 'Fee schedule could not be created for % / % / %', r.clearance_type, r.category, r.classification; end if;
    if not exists (select 1 from public.fee_schedule_items where fee_schedule_id = sched_id) then
      for i in 1 .. array_length(r.names, 1) loop
        insert into public.fee_schedule_items (fee_schedule_id, component_name, amount) values (sched_id, r.names[i], r.amounts[i]);
      end loop;
    end if;
  end loop;
end $$;

update public.business_classifications k set active = false
from (values
  ('Watch Repair Shop', 'Small'),
  ('Watch Repair Shop', 'Large')
) as v(category, name)
join public.business_categories c on c.name = v.category
where k.category_id = c.id and k.name = v.name and k.active;

update public.business_categories set active = false
where name in ('Household Beauty Products Manufacturers / Repacking') and active;
